-- things outside the copied schemas: auth trigger, storage policies, realtime tables, scheduled jobs
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
create policy "Authenticated users upload avatars" on storage.objects as PERMISSIVE for INSERT to public with check (((bucket_id = 'avatars'::text) AND (auth.role() = 'authenticated'::text)));
create policy "Authenticated users upload forum media" on storage.objects as PERMISSIVE for INSERT to public with check (((bucket_id = 'forum-media'::text) AND (auth.role() = 'authenticated'::text)));
create policy "Public can read avatars" on storage.objects as PERMISSIVE for SELECT to public using ((bucket_id = 'avatars'::text));
create policy "Public can read forum media" on storage.objects as PERMISSIVE for SELECT to public using ((bucket_id = 'forum-media'::text));
create policy "Users update own avatars" on storage.objects as PERMISSIVE for UPDATE to public using (((bucket_id = 'avatars'::text) AND (auth.role() = 'authenticated'::text)));
create policy "anyone can read marketplace uploads" on storage.objects as PERMISSIVE for SELECT to public using ((bucket_id = 'marketplace-uploads'::text));
create policy "authenticated users can upload to own folder" on storage.objects as PERMISSIVE for INSERT to public with check (((bucket_id = 'marketplace-uploads'::text) AND (auth.role() = 'authenticated'::text) AND (((storage.foldername(name))[1] = (auth.uid())::text) OR (split_part(name, '/'::text, 1) = (auth.uid())::text))));
create policy cert_share_insert on storage.objects as PERMISSIVE for INSERT to authenticated with check (((bucket_id = 'certificates'::text) AND public.can_write_cert_share(name)));
create policy cert_share_read on storage.objects as PERMISSIVE for SELECT to public using (((bucket_id = 'certificates'::text) AND (name ~~ 'share/%'::text)));
create policy cert_share_update on storage.objects as PERMISSIVE for UPDATE to authenticated using (((bucket_id = 'certificates'::text) AND public.can_write_cert_share(name))) with check (((bucket_id = 'certificates'::text) AND public.can_write_cert_share(name)));
create policy "owners can delete their marketplace uploads" on storage.objects as PERMISSIVE for DELETE to public using (((bucket_id = 'marketplace-uploads'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
create policy "owners can update their marketplace uploads" on storage.objects as PERMISSIVE for UPDATE to public using (((bucket_id = 'marketplace-uploads'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
create policy vdocs_insert on storage.objects as PERMISSIVE for INSERT to anon,authenticated with check ((bucket_id = 'volunteer-docs'::text));
create policy vdocs_read on storage.objects as PERMISSIVE for SELECT to anon,authenticated using ((bucket_id = 'volunteer-docs'::text));
